    private static IReadOnlyList<ManagementReference> ParseReferences(string value){var list=new List<ManagementReference>();foreach(var part in value.Split([',',';','\n'],StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries)){var i=part.IndexOf(':');if(i<=0||i>=part.Length-1)continue;var type=part[..i].Trim();var key=part[(i+1)..].Trim();if(type.Length>0&&key.Length>0)list.Add(new(type,key));}return list.DistinctBy(x=>$"{x.Type}:{x.Key}",StringComparer.OrdinalIgnoreCase).ToArray();}
    private IReadOnlyList<string> CurrentActorRoles=>_roles?.Bindings.Where(x=>x.Status.Equals("Active",StringComparison.OrdinalIgnoreCase)&&x.ActorIdentity.Equals(_roles.CurrentActor,StringComparison.OrdinalIgnoreCase)).Select(x=>x.Role).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase).ToArray()??Array.Empty<string>();
    private static string[] SplitList(string value)=>value.Split([',',';','\n'],StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
    private static string? Null(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();private static DateTimeOffset Utc(DateTime value)=>new(value.Kind==DateTimeKind.Unspecified?DateTime.SpecifyKind(value,DateTimeKind.Local):value).ToUniversalTime();private static DateTimeOffset? UtcNullable(DateTime? value)=>value.HasValue?Utc(value.Value):null;private static string[] Split(string value)=>value.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);
    private static IReadOnlyList<CapacityExceptionInput> ParseExceptions(string value){var list=new List<CapacityExceptionInput>();foreach(var line in value.Split('\n',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries)){var p=line.Split('|',StringSplitOptions.TrimEntries);if(p.Length<4||!DateTime.TryParse(p[0],out var start)||!DateTime.TryParse(p[1],out var end)||!decimal.TryParse(p[2],out var hours))continue;list.Add(new(new DateTimeOffset(start.Date,TimeZoneInfo.Local.GetUtcOffset(start.Date)).ToUniversalTime(),new DateTimeOffset(end.Date.AddDays(1).AddTicks(-1),TimeZoneInfo.Local.GetUtcOffset(end.Date)).ToUniversalTime(),hours,p[3],p.Length>4?p[4]:null));}return list;}

